/// Transport confirmations load receipts generated by actual command execution on fakes.
private struct EngineErrorEnvelope: Decodable {
    struct Failure: Decodable { let kind: String; let note: Note? }
    let error: Failure
}
private actor D8D9Engine: EngineTransport {
    var state: String
    var calls: [(String, [String])] = []
    var fail = false
    var wrongLink = false
    var block = false
    var mixedTimes = false
    var newTurn = false
    var waiting: CheckedContinuation<Void, Never>?
    init(_ state: String) { self.state = state }
    func configure(state: String? = nil, fail: Bool = false, wrongLink: Bool = false, block: Bool = false, mixedTimes: Bool = false, newTurn: Bool = false) {
        if let state { self.state = state }; self.fail = fail; self.wrongLink = wrongLink; self.block = block; self.mixedTimes = mixedTimes; self.newTurn = newTurn
    }
    func isWaiting() -> Bool { waiting != nil }
    func resume() { waiting?.resume(); waiting = nil }
    func requests() -> [(String, [String])] { calls }
    func response<T: Decodable & Sendable>(command: String, arguments: [String], as type: T.Type) async throws -> T {
        calls.append((command, arguments))
        let snapshotState = state; let snapshotWrong = wrongLink
        if block { block = false; await withCheckedContinuation { waiting = $0 } }
        if fail {
            let data = try Data(contentsOf: ComponentTests.root.appendingPathComponent("Fixtures/history.d9_error.json"))
            let envelope = try JSONDecoder().decode(EngineErrorEnvelope.self, from: data)
            throw EngineCommandError(kind: envelope.error.kind, note: envelope.error.note)
        }
        let url = ComponentTests.root.appendingPathComponent("Fixtures/\(command).\(arguments.contains("--confirm") && FileManager.default.fileExists(atPath: ComponentTests.root.appendingPathComponent("Fixtures/\(command).\(snapshotState)_applied.json").path) ? snapshotState + "_applied" : snapshotState).json")
        var object = try #require(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        if let failure = object["error"] {
            let envelope = try JSONDecoder().decode(EngineErrorEnvelope.self, from: JSONSerialization.data(withJSONObject: ["error": failure]))
            throw EngineCommandError(kind: envelope.error.kind, note: envelope.error.note)
        }
        if mixedTimes, command == "history", var events = object["events"] as? [[String: Any]], events.count >= 3 {
            for i in events.indices { events[i]["at"] = "2026-10-05T13:00:00Z" }
            events[0]["at"] = "2026-10-05T14:00:00.900Z"
            events[1]["at"] = "2026-10-05T14:00:00Z"
            events[2]["at"] = "2026-10-05T14:00:00.000Z"
            object["events"] = events
        }
        if newTurn, command == "merge-show", var turns = object["unsynced"] as? [[String: Any]],
           var turn = turns.last, var order = object["order"] as? [Int] {
            turn["id"] = 777; turn["seq"] = 99; turn["first_line"] = "New completed turn"
            turns.append(turn); order.append(777)
            object["unsynced"] = turns; object["order"] = order
            if var presets = object["presets"] as? [[String: Any]] {
                for i in presets.indices { presets[i]["order"] = order }
                object["presets"] = presets
            }
        }
        if newTurn, command == "merge", var order = object["order"] as? [Int] {
            order.append(777); object["order"] = order; object["plan_id"] = "p_new_completed_turn"
        }
        if snapshotWrong { object["link_id"] = 999 }
        return try JSONDecoder().decode(type, from: JSONSerialization.data(withJSONObject: object))
    }
}

