    @MainActor @Test func eachNewStateProducesPNGInBothThemes() async throws {
        let directory = ComponentTests.root.appendingPathComponent("Snapshots")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        for state in ["u1", "u2", "u3", "u4", "u5", "u6", "u7", "u8", "large", "split"] {
            let model = MergeViewModel(engine: D8D9Engine("d8_" + state)); await model.load(link: 3)
            for theme in Theme.allCases { try render(MergeView(model: model), name: "D8-\(state)", theme: theme, directory: directory) }
        }
        let history = HistoryViewModel(engine: D8D9Engine("d9_all_kinds")); await history.load(link: 3)
        for theme in Theme.allCases { try render(HistoryView(model: history), name: "D9-history", theme: theme, directory: directory) }
        for command in ["undo", "restore"] {
            for state in command == "undo" ? ["cut", "shorter", "replying", "attached", "t8", "t10", "t10b", "t11", "u9"] : ["cut", "shorter", "t9", "t10c"] {
                let model = ActionReviewViewModel(engine: D8D9Engine("d9_" + state))
                await model.load(command == "undo" ? .undo(link: 3, event: 4) : .restore(link: 3, event: 9))
                for theme in Theme.allCases { try render(ActionReviewView(model: model).padding(20), name: "D9-\(command)-\(state)", theme: theme, directory: directory) }
            }
        }
    }
    @MainActor private func render<V: View>(_ view: V, name: String, theme: Theme, directory: URL) throws {
        // A render proves image production; visual assessment is separate.
        let renderer = ImageRenderer(content: view.frame(width: 760).frame(minHeight: 120).background(theme.background).batonTheme(theme).environment(\.batonSnapshotPresentation, true))
        let image = try #require(renderer.nsImage); #expect(image.size.width == 760 && image.size.height > 100)
        let tiff = try #require(image.tiffRepresentation)
        let bitmap = try #require(NSBitmapImageRep(data: tiff))
        let data = try #require(bitmap.representation(using: .png, properties: [:]))
        try data.write(to: directory.appendingPathComponent("\(name)-\(theme.rawValue).png"))
    }
